 "أحمد، دعاء مطلق، وتخصيصه بالمرآة حديثه ضعيف": "আহমাদ: এটি সাধারণ দোয়া, আয়নার সাথে নির্দিষ্ট করার বর্ণনাটি দুর্বল",
 "مسلم، تُقال عند الشهادتين، غُفر له ذنبه": "মুসলিম: দুই শাহাদাতের সময় বলা হয়; তার গুনাহ ক্ষমা করা হয়",
 "مسلم، من صلى عليّ صلاة صلى الله عليه بها عشرًا": "মুসলিম: “যে ব্যক্তি আমার উপর একবার দরুদ পড়ে, আল্লাহ এর বিনিময়ে তার উপর দশবার রহমত বর্ষণ করেন”",
 "البخاري، حلَّت له شفاعتي يوم القيامة": "বুখারি: “কিয়ামতের দিন তার জন্য আমার শাফায়াত অবধারিত হয়ে যায়”",
 "أبو داود والترمذي، غُفر له وإن كان فرَّ من الزحف": "আবু দাউদ ও তিরমিজি: তাকে ক্ষমা করা হয়, যদিও সে যুদ্ধক্ষেত্র থেকে পালিয়ে থাকে",
 "أبو داود والترمذي، كان يُعَدُّ له في المجلس مئة مرة": "আবু দাউদ ও তিরমিজি: একই মজলিসে নবী ﷺ এটি 100 বার বলতেন বলে গণনা করা হতো",
 "الترمذي، دعوة ذي النون، ما دعا بها مسلم في شيء إلا استجاب الله له": "তিরমিজি: যুন-নুন (নবী ইউনুস)-এর দোয়া; কোনো মুসলিম যেকোনো বিষয়ে এ দোয়া করলে আল্লাহ অবশ্যই তা কবুল করেন",
 "الترمذي وأبو داود، كفارة المجلس": "তিরমিজি ও আবু দাউদ: মজলিসের কাফফারা",
 "البخاري ومسلم، من قالها في يوم مئة مرة حُطَّت خطاياه وإن كانت مثل زبد البحر": "বুখারি ও মুসলিম: যে ব্যক্তি দিনে 100 বার এটি বলে, তার গুনাহ মুছে ফেলা হয়, যদিও তা সমুদ্রের ফেনার সমান হয়",
 "البخاري، سيد الاستغفار، من قالها موقنًا بها فمات دخل الجنة": "বুখারি: সাইয়্যিদুল ইস্তিগফার (ক্ষমা প্রার্থনার শ্রেষ্ঠ দোয়া), যে ব্যক্তি দৃঢ় বিশ্বাসের সাথে এটি বলে তারপর মারা যায়, সে জান্নাতে প্রবেশ করবে",
 "مسلم، كان ﷺ يتوب إلى الله في اليوم مئة مرة": "মুসলিম: নবী ﷺ দিনে 100 বার আল্লাহর কাছে তওবা করতেন",
 "البخاري، كان ﷺ يقولها للمريض": "বুখারি: নবী ﷺ রোগীর জন্য এটি বলতেন",
 "أبو داود والترمذي، من عاد مريضًا فقالها سبعًا عافاه الله": "আবু দাউদ ও তিরমিজি: যে ব্যক্তি কোনো রোগীকে দেখতে গিয়ে এটি সাতবার বলে, আল্লাহ সেই রোগীকে সুস্থ করে দেন",
 "مسلم، يضع يده على موضع الألم ويقولها ثلاثًا": "মুসলিম: ব্যথার স্থানে হাত রেখে তিনবার এটি বলবে",
 "مسلم، يقولها سبعًا ويده على موضع الألم": "মুসলিম: ব্যথার স্থানে হাত রেখে সাতবার এটি বলবে",
 "الترمذي وابن ماجه، من قالها في مرضه ثم مات لم تطعمه النار": "তিরমিজি ও ইবনে মাজাহ: যে ব্যক্তি অসুস্থ অবস্থায় এটি বলে তারপর মারা যায়, জাহান্নামের আগুন তাকে স্পর্শ করবে না",
 "البخاري، قالها إبراهيم ومحمد عليهما السلام": "বুখারি: ইবরাহিম ও মুহাম্মাদ (আলাইহিমাস সালাম) এটি বলেছিলেন",
 "الترمذي، لقضاء الدين ولو كان مثل جبل": "তিরমিজি: ঋণ পরিশোধের জন্য, যদিও তা পাহাড়সম হয়",
 "البخاري ومسلم، تُقال عند الغضب فيذهب ما يجد": "বুখারি ও মুসলিম: রাগের সময় বলা হয়, ফলে সে যা অনুভব করে তা দূর হয়ে যায়",
 "ابن حبان، إذا استصعب عليك أمر": "ইবনে হিব্বান: কোনো কাজ আপনার কাছে কঠিন মনে হলে",
 "مسلم، في الصلاة على الميت": "মুসলিম: জানাজার নামাজে",
 "أبو داود والترمذي وابن ماجه": "আবু দাউদ, তিরমিজি ও ইবনে মাজাহ",
 "البخاري ومسلم، في التعزية": "বুখারি ও মুসলিম: সমবেদনা জানানোর সময়",
 "مسلم، عند المصيبة": "মুসলিম: মুসিবতের সময়",
 "أبو داود، تلقين المحتضر، من كان آخر كلامه لا إله إلا الله دخل الجنة": "আবু দাউদ: মুমূর্ষু ব্যক্তিকে তালকিন, যার শেষ কথা হবে লা ইলাহা ইল্লাল্লাহ, সে জান্নাতে প্রবেশ করবে",
 "مسلم، عند إغماض الميت": "মুসলিম: মৃত ব্যক্তির চোখ বন্ধ করার সময়",
 "أبو داود وابن ماجه، في الصلاة على الميت": "আবু দাউদ ও ইবনে মাজাহ: জানাজার নামাজে",
 "البخاري تعليقًا، في الصلاة على الطفل": "বুখারি, মুআল্লাক সূত্রে (পূর্ণ সনদ ছাড়া): শিশুর জানাজার নামাজে",
 "أبو داود، عند إدخال الميت القبر": "আবু দাউদ: মৃত ব্যক্তিকে কবরে নামানোর সময়",
 "أبو داود، استغفروا لأخيكم وسلوا له التثبيت": "আবু দাউদ: তোমাদের ভাইয়ের জন্য ক্ষমা প্রার্থনা করো এবং তার জন্য দৃঢ়তা চাও",
 "مسلم، عند زيارة القبور": "মুসলিম: কবর জিয়ারতের সময়",
 "الترمذي وابن ماجه، عند دخول السوق": "তিরমিজি ও ইবনে মাজাহ: বাজারে প্রবেশের সময়",
 "الترمذي والدارمي، عند رؤية الهلال": "তিরমিজি ও দারিমি: নতুন চাঁদ দেখার সময়",
