 "دعاء دخول المنزل والخروج": "ঘরে প্রবেশ ও বের হওয়ার দোয়া",
 "دعاء دخول الخلاء والخروج": "শৌচাগারে প্রবেশ ও বের হওয়ার দোয়া",
