 "من ارتفاع الشمس إلى قبيل الزوال": "সূর্য উপরে ওঠার পর থেকে সূর্য ঢলে পড়ার একটু আগ পর্যন্ত",
 "من الزوال إلى العصر": "সূর্য ঢলে পড়া থেকে আসর পর্যন্ত",
