 "الترمذي، أكثر دعاء النبي ﷺ": "তিরমিজি: নবী ﷺ সবচেয়ে বেশি যে দোয়া করতেন",
 "أبو داود، تهنئة المتزوج": "আবু দাউদ: নববিবাহিতকে শুভেচ্ছা জানানো",
 "مسلم، الدعاء للميت": "মুসলিম: মৃত ব্যক্তির জন্য দোয়া",
 "مسلم، عند لقاء العدو": "মুসলিম: শত্রুর মুখোমুখি হলে",
 "أبو داود والترمذي، توديع المسافر": "আবু দাউদ ও তিরমিজি: মুসাফিরকে বিদায় জানানো",
 "الغسل يوم الجمعة، فهو آكد السنن في هذا اليوم": "জুমার দিন গোসল করা, এটি এ দিনের সবচেয়ে গুরুত্বপূর্ণ সুন্নাত",
 "التطيب ولبس أحسن الثياب": "সুগন্ধি ব্যবহার করা ও সবচেয়ে ভালো পোশাক পরা",
 "قراءة سورة الكهف، فمن قرأها أضاء له النور ما بين الجمعتين": "সূরা আল-কাহফ তিলাওয়াত করা; যে ব্যক্তি তা পড়ে, দুই জুমার মধ্যবর্তী সময়জুড়ে তার জন্য নূর আলোকিত থাকে",
 "التبكير إلى المسجد والمشي إليه": "আগেভাগে মসজিদে যাওয়া এবং হেঁটে যাওয়া",
 "الإكثار من الصلاة على النبي ﷺ في يومها وليلتها": "জুমার দিনে ও রাতে নবী ﷺ-এর উপর বেশি বেশি দরুদ পড়া",
 "الإنصات للخطبة، فمن لغا فلا جمعة له": "চুপ করে খুতবা শোনা, কারণ যে অনর্থক কথা বলে, তার জুমা নেই",
 "تحري ساعة الإجابة في آخر ساعة بعد العصر": "আসরের পরের শেষ সময়টিতে দোয়া কবুলের মুহূর্ত খোঁজা",
