 "ما يقول المسلم إذا مدح المسلم": "এক মুসলিম অন্য মুসলিমের প্রশংসা করলে যা বলবে",
 "ما يقول المسلم إذا زكي": "মুসলিমের প্রশংসা করা হলে সে যা বলবে",
 "كيف يلبي المحرم في الحج أو العمرة؟": "হজ বা ওমরাহে ইহরামধারী কীভাবে তালবিয়া পড়বে?",
 "التكبير إذا أتى الركن الأسود": "হাজরে আসওয়াদের কোণে পৌঁছলে তাকবির",
 "الدعاء بين الركن اليماني والحجر الأسود": "রুকনে ইয়ামানি ও হাজরে আসওয়াদের মাঝে দোয়া",
 "دعاء الوقوف على الصفا والمروة": "সাফা ও মারওয়ায় দাঁড়ানোর দোয়া",
 "الدعاء يوم عرفة": "আরাফার দিনের দোয়া",
 "الذكر عند المشعر الحرام": "মাশআরুল হারামে জিকির",
 "التكبير عند رمي الجمار مع كل حصاة": "জামরায় প্রতিটি কঙ্কর নিক্ষেপের সাথে তাকবির",
 "دعاء التعجب والأمر السار": "বিস্ময় ও আনন্দের সময় দোয়া",
 "ما يفعل من أتاه أمر يسره": "আনন্দদায়ক কিছু ঘটলে যা করবে",
 "ما يقول من أحس وجعا في جسده": "শরীরে ব্যথা অনুভব করলে যা বলবে",
 "دعاء من خشي أن يصيب شيئا بعينه": "নিজের বদনজর লাগার আশঙ্কা হলে দোয়া",
 "ما يقال عند الفزع": "ভয় পেলে যা বলবে",
 "ما يقول عند الذبح أو النحر": "পশু জবাই বা কুরবানি করার সময় যা বলবে",
 "ما يقول لرد كيد مردة الشياطين": "অবাধ্য শয়তানদের চক্রান্ত প্রতিহত করতে যা বলবে",
 "الاستغفار و التوبة": "ইস্তিগফার ও তওবা",
 "فضل التسبيح و التحميد، و التهليل، و التكبير": "সুবহানাল্লাহ, আলহামদুলিল্লাহ, লা ইলাহা ইল্লাল্লাহ ও আল্লাহু আকবারের ফজিলত",
 "كيف كان النبي يسبح؟": "নবী কীভাবে তাসবিহ পড়তেন?",
 "من أنواع الخير والآداب الجامعة": "বিভিন্ন ধরনের ভালো কাজ ও সামগ্রিক আদব",
 "فضل التسبيح و التحميد": "সুবহানাল্লাহ ও আলহামদুলিল্লাহর ফজিলত",
