 "تصلك التنبيهات ما دام التطبيق مفتوحاً أو في الخلفية، وتصل على أوسع نطاق حين يُثبَّت التطبيق على الجهاز.": "অ্যাপ খোলা থাকলে বা ব্যাকগ্রাউন্ডে চললে অ্যালার্ট আসে, আর ডিভাইসে অ্যাপ ইনস্টল করা থাকলে সবচেয়ে নির্ভরযোগ্যভাবে আসে।",
 "عن سُنّتي": "Sunnati সম্পর্কে",
 "ما الذي يعمل هنا، وكيف": "এখানে কী কাজ করে, এবং কীভাবে",
 "شعار سُنّتي: محراب يطل على سماء الغروب وفيه مئذنة وهلال": "Sunnati অ্যাপের লোগো: সূর্যাস্তের আকাশমুখী একটি মিহরাব, যাতে একটি মিনার ও একটি নতুন চাঁদ",
 "مصحف ومواقيت وأذكار وسنن في جهازك": "কুরআন, নামাজের সময়, জিকির ও সুন্নাত আপনার ডিভাইসে",
 "الشعار محراب يطل على سماء الوقت، وفيه مئذنة على الساحل وهلال فوقها": "লোগোটি সময়ের আকাশমুখী একটি মিহরাব, যাতে উপকূলে একটি মিনার এবং তার উপরে একটি নতুন চাঁদ",
 "حمّل سُنّتي من متجر آبل": "App Store থেকে Sunnati ডাউনলোড করুন",
 "حمّل سُنّتي من Google Play": "Google Play থেকে Sunnati ডাউনলোড করুন",
 "سُنّتي على متجر آبل وعلى Google Play، فثبّته من متجر جهازك لتصلك تحديثاته منه": "Sunnati আছে App Store ও Google Play স্টোরে, তাই আপনার ডিভাইসের স্টোর থেকে ইনস্টল করুন, যাতে সেখান থেকেই হালনাগাদ পান",
 "سُنّتي يعمل كاملاً على جهازك، فالمصحف كله محفوظ معك وأوقات الصلاة تُحسب فلكياً على الجهاز نفسه دون طلب من أي خادم، ثم تبقى الأذكار والقبلة وتتبع السنن متاحة ولو انقطع الإنترنت.": "Sunnati পুরোপুরি আপনার ডিভাইসেই চলে: পুরো কুরআন আপনার কাছে সংরক্ষিত, আর নামাজের সময় কোনো সার্ভারের সাহায্য ছাড়াই ডিভাইসেই জ্যোতির্বিদ্যার হিসাবে নির্ণয় করা হয়। ইন্টারনেট না থাকলেও জিকির, কিবলা ও সুন্নাত ট্র্যাকার ব্যবহার করা যায়।",
 "ما الذي يحتاج إنترنت": "কী কী ইন্টারনেট লাগে",
 "تلاوة القارئ والإذاعة والتفسير وحدها تحتاج اتصالاً، وما عدا ذلك يعمل بلا شبكة.": "কেবল কারির তিলাওয়াত, রেডিও ও তাফসিরের জন্য সংযোগ লাগে; বাকি সবকিছু নেটওয়ার্ক ছাড়াই চলে।",
 "المصادر": "উৎস",
 "نص المصحف برواية حفص عن عاصم بالرسم العثماني، والأذكار من حصن المسلم، والأحاديث من الأربعين النووية، ثم التلاوات من شبكة القرآن المفتوحة، وخريطة المساجد وبياناتها من": "কুরআনের পাঠ হাফস আন আসিম রেওয়ায়েত অনুযায়ী উসমানি লিপিতে, জিকির হিসনুল মুসলিম থেকে, হাদিস ইমাম নববীর চল্লিশ হাদিস থেকে, তিলাওয়াত উন্মুক্ত কুরআন নেটওয়ার্ক থেকে, আর মসজিদের মানচিত্র ও এর তথ্যের উৎস",
