 "كان النبي ﷺ لا ينام حتى يقرأ ألم تنزيل السجدة وتبارك الذي بيده الملك": "নবী ﷺ “আলিফ লাম মিম তানজিল” (আস-সাজদা) ও “তাবারাকাল্লাযি বিয়াদিহিল মুলক” (আল-মুলক) না পড়ে ঘুমাতেন না",
 "إذا أويت إلى فراشك فاقرأ آية الكرسي، لن يزال عليك من الله حافظ": "বিছানায় যাওয়ার সময় আয়াতুল কুরসি পড়ুন, আল্লাহর পক্ষ থেকে আপনার জন্য একজন রক্ষক থাকবে",
 "أكثِر من الصلاة على النبي ﷺ، فإن صلاتكم معروضة عليه": "নবী ﷺ-এর উপর বেশি বেশি দরুদ পড়ুন, কারণ আপনাদের দরুদ তাঁর কাছে পেশ করা হয়",
 "صيام الغد": "আগামীকালের রোজা",
 "{0}، فاعقد النية ولا تدع السحور": "{0}: নিয়ত করে নিন এবং সেহরি বাদ দেবেন না",
 "اقرأ سورة الكهف، وأكثِر من الصلاة على النبي ﷺ قبل الصلاة": "সূরা আল-কাহফ পড়ুন, এবং নামাজের আগে নবী ﷺ-এর উপর বেশি বেশি দরুদ পড়ুন",
 "قيام الليل": "তাহাজ্জুদ",
 "هذا الثلث الأخير، وفيه ينزل ربنا تبارك وتعالى": "এখন রাতের শেষ তৃতীয়াংশ, এ সময় আমাদের রব তাবারাকা ওয়া তাআলা অবতরণ করেন",
 "تعذّرت الإشعارات على هذا الجهاز، فلن يصلك التذكير": "এই ডিভাইসে নোটিফিকেশন চালু করা যায়নি, তাই রিমাইন্ডার আসবে না",
 "الإشعارات مغلقة لسُنّتي، فاسمح بها من الإعدادات ليصلك التذكير": "Sunnati অ্যাপের নোটিফিকেশন বন্ধ আছে। রিমাইন্ডার পেতে সেটিংস থেকে অনুমতি দিন।",
 "لم يُسمح بالإشعارات، فلن يصلك التذكير": "নোটিফিকেশনের অনুমতি দেওয়া হয়নি, তাই রিমাইন্ডার আসবে না",
 "من مغرب الخميس إلى فجر الجمعة، وتُعرض كلما فتحت التطبيق حتى تؤجّلها أو تُخفيها": "বৃহস্পতিবার মাগরিব থেকে শুক্রবার ফজর পর্যন্ত। স্থগিত বা লুকিয়ে না রাখা পর্যন্ত প্রতিবার অ্যাপ খুললে এটি দেখানো হবে।",
