 "لا تُذكّرني": "মনে করিয়ে দেবেন না",
 "اقرأ سورة الكهف، وتُجزئ ليلة الجمعة ويومها": "সূরা আল-কাহফ পড়ুন; জুমার রাতে বা জুমার দিনে পড়লেই যথেষ্ট",
 "أكثِر من الدعاء، ففي الجمعة ساعة لا يُرد فيها سائل": "বেশি বেশি দোয়া করুন, কারণ জুমার দিনে এমন একটি সময় আছে, যখন কোনো প্রার্থনাকারীকে ফিরিয়ে দেওয়া হয় না",
 "اغتسل غداً وتطيّب وبكّر إلى المسجد": "আগামীকাল গোসল করুন, সুগন্ধি ব্যবহার করুন এবং আগেভাগে মসজিদে যান",
 "من مغرب الخميس إلى فجر الجمعة": "বৃহস্পতিবার মাগরিব থেকে শুক্রবার ফজর পর্যন্ত",
