 "ملاحظات على سُنّتي": "Sunnati সম্পর্কে মতামত",
 "إن نفعك سُنّتي فقيّمه في المتجر، فتقييمك يدلّ غيرك عليه": "Sunnati থেকে উপকৃত হলে স্টোরে রেটিং দিন, আপনার রেটিং অন্যদের এর সন্ধান দেয়",
 "قيّمه": "রেটিং দিন",
 "أهلاً بك في سُنّتي": "Sunnati অ্যাপে স্বাগতম",
 "مصحفك ومواقيت صلاتك وأذكارك وسننك في مكان واحد يعمل كله بلا إنترنت، وهذه جولة قصيرة فيه لا تأخذ منك دقيقة.": "আপনার কুরআন, নামাজের সময়, জিকির ও সুন্নাত এক জায়গায়, যা পুরোপুরি ইন্টারনেট ছাড়াই চলে। এখানে একটি সংক্ষিপ্ত পরিচিতি, এক মিনিটও লাগবে না।",
 "ابدأ الجولة": "পরিচিতি শুরু করুন",
 "العدّ إلى الصلاة القادمة في محراب يتبدّل ضوؤه مع الوقت، فالمس المحراب لترى سماء الوقت على الشاشة كلها.": "পরবর্তী নামাজ পর্যন্ত সময় গণনা, একটি মিহরাবে যার আলো সময়ের সাথে বদলায়। পুরো পর্দায় সময়ের আকাশ দেখতে মিহরাবে স্পর্শ করুন।",
 "مواقيت الصلوات لمدينتك، واضغط الصلاة بعد أدائها لتسجّل كيف صلّيتها وتتابع شهرك كله.": "আপনার শহরের নামাজের সময়। নামাজ আদায়ের পর তাতে চেপে কীভাবে আদায় করেছেন তা লিখে রাখুন এবং পুরো মাসের হিসাব রাখুন।",
 "المصحف كاملاً في جهازك برواية حفص بالرسم العثماني، ومعه التفسير والتلاوة بأصوات القرّاء.": "পুরো কুরআন আপনার ডিভাইসে, হাফস রেওয়ায়েতে উসমানি লিপিতে, সাথে তাফসির ও বিভিন্ন কারির কণ্ঠে তিলাওয়াত।",
 "سنن يومك من الاستيقاظ إلى النوم، فسجّل ما أدّيته منها ليُحسب في وردك.": "ঘুম থেকে জাগা থেকে ঘুমানো পর্যন্ত আপনার দিনের সুন্নাত। যা আদায় করেছেন তা চিহ্নিত করুন, যাতে আপনার ওযিফায় গণনা হয়।",
 "القبلة والمساجد القريبة والأذكار وصفة العمرة والتذكيرات والإعدادات، وفي الإعدادات تجد هذه الجولة متى أردتها.": "কিবলা, কাছের মসজিদ, জিকির, ওমরাহর নিয়ম, রিমাইন্ডার ও সেটিংস; আর সেটিংসে যখন চান এই পরিচিতি পাবেন।",
